/* @lc app=leetcode id=1648 lang=kotlin */
class Solution { fun maxProfit(inventory: IntArray, orders: Int): Int = inventory.map { it.toLong() }.sortedDescending().let { sorted -> longArrayOf(orders.toLong(), 0L).let { s -> sorted.indices.takeWhile { s[0] > 0 }.forEach { i -> (sorted[i] - if (i + 1 < sorted.size) sorted[i + 1] else 0L).let { diff -> minOf(s[0], diff * (i + 1L)).let { count -> (count / (i + 1L)).let { k -> (count % (i + 1L)).let { r -> s[0] -= count.also { s[1] = (s[1] + (i + 1L) * (sorted[i] + sorted[i] - k + 1) * k / 2 + r * (sorted[i] - k)) % 1000000007 } } } } } }.let { s[1].toInt() } } }}